    // Similarly b = c | (x & ~mask)

    // The number of distinct masks is 2^(popcount(x))
    // Each mask gives a pair (a, b). Since (a,b) and (b,a) are different ordered pairs,
    // and each mask gives one ordered pair, the total is 2^(popcount(x)).

    // But we need a > 0 and b > 0.
    // a = 0 when c = 0 and mask = 0 (all bits of x go to b)
    // b = 0 when c = 0 and mask = x (all bits of x go to a)

    if ($c == 0) {
        // Subtract 2 for the cases where a=0 or b=0
        $total -= 2;
    }

    return $total;
}

$input = trim(fgets(STDIN));
$parts = explode(' ', $input);
$s = (int)$parts[0];
$x = (int)$parts[1];

echo solve($s, $x) . "\n";
?>
